use vstd::prelude::*;

verus! {

    /// Stacks two equal‐length vectors `a` and `b` vertically into
    /// a 2×n matrix represented as a `Vec<Vec<f32>>`.
    ///
    /// # Arguments
    ///
    /// * `a` - A vector of `f32` values (length n).
    /// * `b` - A vector of `f32` values (also length n).
    ///
    /// # Returns
    ///
    /// A `Vec<Vec<f32>>` with two rows:
    /// - row 0 is `a`
    /// - row 1 is `b`
    fn vstack(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>>
        requires
            a.len() == b.len(),
        ensures
            |res: Vec<Vec<f32>>| 
                // result has exactly two rows
                res.len() == 2
                // row 0 is exactly `a`
                && res[0] == a
                // row 1 is exactly `b`
                && res[1] == b
    {
        vec![a, b]
    }

    /// Alias for `vstack`: stacks two vectors into a 2×n outer matrix.
    fn make_outer(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>>
        requires
            a.len() == b.len(),
        ensures
            |res: Vec<Vec<f32>>|
                // obviously the same specification as `vstack`
                res.len() == 2
                && res[0] == a
                && res[1] == b
    {
        vstack(a, b)
    }
}

